class Section:
    def __init__(self, name):
        self.name = name

    def __enter__(self):
        print("enter", self.name)
        return self

    def __exit__(self, exc_type, exc, tb):
        print("exit", self.name)
        return False

with Section("A") as s:
    print("inside", s.name)
print("after")

from contextlib import contextmanager

@contextmanager
def tag(name):
    print("<" + name + ">")
    try:
        yield
    finally:
        print("</" + name + ">")

with tag("b"):
    print("bold text")
try:
    with tag("i"):
        raise ValueError("oops")
except ValueError as e:
    print("caught", e)

